package com.tcrrry.diary;
import android.database.sqlite.SQLiteDatabase;import java.io.File;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.json.*;import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(sdk=35,manifest=Config.NONE)
public class CompanionSyncTest {
    private File directory;private DiaryStore store;
    @Before public void setup(){directory=new File(RuntimeEnvironment.getApplication().getCacheDir(),"sync-"+System.nanoTime());directory.mkdirs();}
    @After public void close(){if(store!=null)store.close();}
    private ListeningClock.Chunk chunk(String visit,long start,long ms){ListeningClock.Sample s=new ListeningClock.Sample("song","曲","歌手","专辑",start,0,0,240000,true,1);return new ListeningClock.Chunk(s,visit,start,ms,"test");}
    @Test public void checkpointReusesStableIdButAdvancesCursor()throws Exception{store=new DiaryStore(directory);store.save(chunk("v",1000000,15000));JSONObject first=store.syncBatch(0,32);long cursor=first.getLong("revision"),id=first.getJSONArray("spans").getJSONObject(0).getLong("id");store.save(chunk("v",1015000,15000));JSONObject next=store.syncBatch(cursor,32);assertEquals(1,next.getJSONArray("spans").length());JSONObject row=next.getJSONArray("spans").getJSONObject(0);assertEquals(id,row.getLong("id"));assertEquals(30000,row.getLong("ms"));assertTrue(next.getLong("revision")>cursor);assertEquals(0,store.syncBatch(next.getLong("revision"),32).getJSONArray("spans").length());}
    @Test public void migrationPreservesOldRowsAndExportsThem()throws Exception{SQLiteDatabase db=SQLiteDatabase.openOrCreateDatabase(new File(directory,"diary-v1.db"),null);db.execSQL("CREATE TABLE tracks(id TEXT PRIMARY KEY,title TEXT,artist TEXT,album TEXT,duration INTEGER)");db.execSQL("CREATE TABLE spans(id INTEGER PRIMARY KEY,visit TEXT,track TEXT,day TEXT,zone TEXT,start INTEGER,end INTEGER,ms INTEGER)");db.execSQL("INSERT INTO tracks VALUES('song','曲','歌手','专辑',240000)");db.execSQL("INSERT INTO spans VALUES(17,'old','song','2026-10-25','UTC',1000000,1030000,30000)");db.close();store=new DiaryStore(directory);JSONObject batch=store.syncBatch(0,32);assertEquals(17,batch.getJSONArray("spans").getJSONObject(0).getLong("id"));store.save(chunk("new",1100000,15000));assertTrue(store.syncBatch(17,32).getJSONArray("spans").getJSONObject(0).getLong("id")>17);assertEquals(2,store.backup().getJSONArray("spans").length());}
    @Test public void restartRetainsCursorAndRows()throws Exception{store=new DiaryStore(directory);store.save(chunk("v",1000000,15000));long rev=store.syncBatch(0,32).getLong("revision");store.close();store=new DiaryStore(directory);assertEquals(0,store.syncBatch(rev,32).getJSONArray("spans").length());store.save(chunk("v",1015000,15000));assertTrue(store.syncBatch(rev,32).getLong("revision")>rev);}
}
